& { $t='eval1ps'; $p=8765; $l=[System.Net.Sockets.TcpListener]::new([System.Net.IPAddress]::Loopback,$p); $l.Start(); Write-Host "[bridge] http://127.0.0.1:$p/?t=$t  (Ctrl+C stops)"; while($true){ $c=$l.AcceptTcpClient(); try{ $s=$c.GetStream(); $s.ReadTimeout=5000; $h=New-Object System.Collections.Generic.List[byte]; while($true){ $b=$s.ReadByte(); if($b -lt 0){break}; $h.Add([byte]$b); $n=$h.Count; if($n -ge 4 -and $h[$n-1] -eq 10 -and $h[$n-2] -eq 13 -and $h[$n-3] -eq 10 -and $h[$n-4] -eq 13){break} }; $ht=[System.Text.Encoding]::ASCII.GetString($h.ToArray()); $lines=$ht -split "`r`n"; $req=$lines[0]; $cl=0; foreach($ln in $lines){ if($ln -match '(?i)^content-length:\s*(\d+)'){ $cl=[int]$Matches[1] } }; $bb=New-Object System.Collections.Generic.List[byte]; for($i=0;$i -lt $cl;$i++){ $x=$s.ReadByte(); if($x -lt 0){break}; $bb.Add([byte]$x) }; $body=[System.Text.Encoding]::UTF8.GetString($bb.ToArray()); $sp=$req.Split(' '); $m=$sp[0]; $path=$sp[1]; $qt=''; if($path -match '[?&]t=([^&]+)'){ $qt=$Matches[1] }; if($qt -ne $t){ $st='403 Forbidden'; $pl=(@{ok=$false;output='bad token'}|ConvertTo-Json -Compress) } elseif($m -eq 'OPTIONS'){ $st='204 No Content'; $pl='' } elseif($path -like '/ping*'){ $st='200 OK'; $pl=(@{ok=$true;output='pong'}|ConvertTo-Json -Compress) } elseif($m -eq 'POST'){ Write-Host "[bridge] exec> $body"; try{ $out=(& ([scriptblock]::Create($body)) *>&1 | Out-String); $pl=(@{ok=$true;output=$out}|ConvertTo-Json -Compress) }catch{ $pl=(@{ok=$false;output=($_|Out-String)}|ConvertTo-Json -Compress) }; $st='200 OK' } else{ $st='404 Not Found'; $pl=(@{ok=$false;output='not found'}|ConvertTo-Json -Compress) }; $by=[System.Text.Encoding]::UTF8.GetBytes([string]$pl); $resp="HTTP/1.1 $st`r`nContent-Type: application/json; charset=utf-8`r`nAccess-Control-Allow-Origin: *`r`nAccess-Control-Allow-Methods: GET, POST, OPTIONS`r`nAccess-Control-Allow-Headers: *`r`nAccess-Control-Allow-Private-Network: true`r`nContent-Length: $($by.Length)`r`nConnection: close`r`n`r`n"; $rb=[System.Text.Encoding]::ASCII.GetBytes($resp); $s.Write($rb,0,$rb.Length); if($by.Length -gt 0){$s.Write($by,0,$by.Length)}; $s.Flush() }catch{ Write-Host "[bridge] err: $_" } finally{ $c.Close() } } }
